parameters.values:
{
  "hero": {
    "type": "hero",
    "eyebrow": "Manzil \u00b7 Project Execution Validation",
    "title": "Welcome back",
    "user": "{{ $json.user.email }}",
    "subtitle": "Live status of your AI workflows, the knowledge base and every report the assistant generates. Every number on this page comes from a published workflow."
  },
  "kpis": {
    "type": "kpiCards",
    "title": "Your project knowledge base",
    "cards": [
      {
        "title": "Projects tracked",
        "value": "{{ $json.projectsCount }}",
        "description": "Covered by the knowledge base",
        "tone": "blue",
        "icon": "briefcase"
      },
      {
        "title": "Indexed passages",
        "value": "{{ $json.projectsTotal }}",
        "description": "From your project documents, ready to cite",
        "tone": "grey",
        "icon": "package"
      },
      {
        "title": "Reports and answers",
        "value": "{{ $json.stats.total }}",
        "description": "Produced in the last {{ $json.stats.days }} days",
        "tone": "green",
        "icon": "activity"
      },
      {
        "title": "Answered first time",
        "value": "{{ $json.stats.successRate }}",
        "description": "Finished without an error",
        "tone": "green",
        "icon": "check"
      },
      {
        "title": "Average answer time",
        "value": "{{ $json.stats.avgTime }}",
        "description": "From question to answer",
        "tone": "orange",
        "icon": "clock"
      }
    ]
  },
  "actionsIntro": {
    "type": "select",
    "name": "projectId",
    "label": "Project",
    "placeholder": "All projects",
    "options": {{ $json.projects }}
  },
  "dashboardToggle": {
    "type": "toggle",
    "name": "dashboard",
    "label": "Include executive dashboard"
  },
  "actions": {
    "type": "buttonGroup",
    "title": "Quick actions",
    "description": "Each action runs its workflow and shows the result here.",
    "buttons": [
      {
        "label": "Project Summary",
        "icon": "briefcase",
        "description": "Overall health, scope and key dates",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Project Summary"
        }
      },
      {
        "label": "Execution Progress",
        "icon": "trending",
        "description": "Planned vs actual progress",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Execution Progress"
        }
      },
      {
        "label": "Material Status",
        "icon": "package",
        "description": "Deliveries, shortages and approvals",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Material Status"
        }
      },
      {
        "label": "Inspection Status",
        "icon": "search",
        "description": "Pending and failed inspections",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Inspection Status"
        }
      },
      {
        "label": "Sign-Off Status",
        "icon": "signature",
        "description": "Approvals awaiting sign-off",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Sign-Off Status"
        }
      },
      {
        "label": "Call Letter Status",
        "icon": "mail",
        "description": "Issued and pending call letters",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Call Letter Status"
        }
      },
      {
        "label": "Work Completion",
        "icon": "check",
        "description": "Completed work packages",
        "eventKey": "manzil.domain",
        "payload": {
          "domain": "Work Completion"
        }
      },
      {
        "label": "Ask the AI",
        "icon": "chat",
        "description": "Open a conversation with Manzil",
        "to": "/app/chat"
      }
    ]
  }
}
